solution:
def token_frequencies(text):
    counts={}
    for token in text.split():
        counts[token]=counts.get(token,0)+1
    return counts

tests:
assert token_frequencies('and And and, and')=={'and':2,'And':1,'and,':1}
assert token_frequencies('x	x\ny')=={'x':2,'y':1}
assert token_frequencies('')=={}
assert token_frequencies('  one  ')=={'one':1}

